sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    var nameSysId = g_form.getValue('name');
    var baseUtils = new GlideAjax('x_1593193_bases.BaseUtils');
    baseUtils.addParam('sysparm_name', 'nameValidation');
    baseUtils.addParam('sysparm_baseName', nameSysId);

    baseUtils.getXMLAnswer(function(response) {
        if (response == 'true') {
            g_form.addErrorMessage('This name already exists registered');
            g_form.setValue('name', '');
        } else {
            g_form.clearMessages();
        }
    });

}
